	ORG	$0100
ENV_TYPE EQU 1 
OS_TYPE EQU 0
LD HL,($0001)
LD (WBOOTBK),HL
; WORK ZERO CLEAR
XOR A
LD HL,__WORK__
LD DE,__WORK__+1
LD BC,__WORKEND__-__WORK__-1
LD (HL),A
LDIR
 CALL RUNTIME_INIT
LD HL,EEC0H   ; LSX-Dodgers 1.62c
LD (_CTCVEC),HL
LD IY,__IYWORK
CALL MAIN
JP 0

VSYNC_PROC:
; function VSYNC_PROC
_VSYNC_PROC_EXIT:
	RET

MAIN:
; function MAIN
	LD	HL,$0028
	CALL	WIDTH
	LD	HL,$0000
	LD	DE,$0000
	CALL	LOCATE
	CALL	MPRNT
	DB	"KEY / STICK(0) / STICK(1)  ESC=END",0
_L0:
	LD	HL,$0000
	CALL	INKEY
	LD	(_V_MAIN_K),HL
	LD	DE,$001B
	OR	A
	SBC	HL,DE
	JP	NZ,_L2
	JP	_L1
_L2:
	LD	HL,$0000
	CALL	STICK
	LD	(_V_MAIN_J0),HL
	LD	HL,$0001
	CALL	STICK
	LD	(_V_MAIN_J1),HL
	LD	HL,$0000
	LD	DE,$0002
	CALL	LOCATE
	CALL	MPRNT
	DB	"KEY ",0
	LD	HL,(_V_MAIN_K)
	CALL	P10
	CALL	MPRNT
	DB	"   ",0
	LD	HL,$0000
	LD	DE,$0003
	CALL	LOCATE
	CALL	MPRNT
	DB	"STICK0 ",0
	LD	HL,(_V_MAIN_J0)
	CALL	P10
	CALL	MPRNT
	DB	"   ",0
	LD	HL,$0000
	LD	DE,$0004
	CALL	LOCATE
	CALL	MPRNT
	DB	"STICK1 ",0
	LD	HL,(_V_MAIN_J1)
	CALL	P10
	CALL	MPRNT
	DB	"   ",0
	LD	HL,(_V_MAIN_J0)
	LD	DE,$0001
	LD	A,H
	AND	D
	LD	H,A
	LD	A,L
	AND	E
	LD	L,A
	LD	DE,$0000
	OR	A
	SBC	HL,DE
	JP	NZ,_L4
	CALL	MPRNT
	DB	"UP   ",0
	JP	_L3
_L4:
	CALL	MPRNT
	DB	"     ",0
_L3:
	LD	HL,$0001
	CALL	VSYNC
	JP	_L0
_L1:
_MAIN_EXIT:
	RET


RUNTIME_INIT:
	RET

; === Runtime Functions ===
DIVHLDE8:
INC E
DEC E
JR NZ, .div81
EX DE, HL
LD HL, 0000
RET
.div81
XOR A
LD B, $10
.div84
ADD HL, HL
ADC A, A
JR C, .div82
CP E
JR C, .div83
.div82
SUB E
INC L
.div83
DJNZ .div84
LD E, A
RET

